Author: Jakub Jelen <jjelen@redhat.com>
Date:   Thu Nov 14 13:16:37 2019 +0100

    pkcs15-cert: Free data on all error exit paths

    https://oss-fuzz.com/testcase-detail/5645063405436928

diff --git a/src/libopensc/pkcs15-cert.c b/src/libopensc/pkcs15-cert.c
index 4bc33304..8606d14a 100644
--- a/src/libopensc/pkcs15-cert.c
+++ b/src/libopensc/pkcs15-cert.c
@@ -384,193 +384,195 @@ sc_pkcs15_read_certificate(struct sc_pkcs15_card *p15card, const struct sc_pkcs1

        cert = malloc(sizeof(struct sc_pkcs15_cert));
        if (cert == NULL) {
                free(der.value);
                LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
        }
        memset(cert, 0, sizeof(struct sc_pkcs15_cert));
        if (parse_x509_cert(ctx, &der, cert)) {
                free(der.value);
                sc_pkcs15_free_certificate(cert);
                LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ASN1_OBJECT);
        }
        free(der.value);

        *cert_out = cert;
        LOG_FUNC_RETURN(ctx, SC_SUCCESS);
 }


